-- Data migration, no schema change.
--
-- Generated by prisma/tools/generate-hr-reference-migration.ts — edit that,
-- re-run it, and commit the result. Do not hand-edit this file: every value
-- below is a copy of a constant in prisma/seed-hr.ts, and the generator is
-- what guarantees the two cannot disagree about what people are paid.
--
-- WHY THIS EXISTS
--
-- The HR module's reference data — the 2022 rate set, its 503 ITS bands, the
-- seniority ladder and the 6 document templates — has only ever been
-- installed by prisma/seed.ts. seed-target-guard.ts refuses to point that
-- script at a non-local database, by design, so a deployed environment has
-- never received any of it.
--
-- Without it the module is not degraded, it is off: findOne() resolves a
-- payroll config to compute a leave balance, so GET /hr/employees/:id
-- answers 404 "No payroll configuration is in force"; so do
-- GET /hr/leave/planning and every payroll calculation and document
-- render; and GET /hr/documents/templates answers with an empty catalogue,
-- which leaves the generator with nothing to issue.
--
-- IDEMPOTENT AND ADDITIVE
--
-- Every statement is INSERT IGNORE against a natural unique key, and the
-- config insert is guarded on its own label, so this is a no-op on an
-- environment already seeded from the current seed.ts. It updates nothing
-- and deletes nothing: an environment that has since edited its rates keeps
-- them, because a migration must never quietly restate what someone is paid.

-- ── 1. The 2022 rate set ────────────────────────────────────────────────

INSERT INTO `hr_payroll_configs` (
  `id`, `effectiveFrom`, `effectiveTo`, `label`,
  `contributionCeiling`, `retirementEmployeeRate`, `amuEmployeeRate`, `amuCeilingAmount`,
  `employerRate`, `employerCappedPortion`, `monthlyHours`,
  `overtimeTier1Rate`, `overtimeTier1MaxHours`, `overtimeTier2Rate`,
  `severanceRatePerYear`, `severanceCnssRate`, `annualLeaveDays`,
  `seniorityIncludedInGross`, `capRetirementEmployee`, `leaveCarryOverCapDays`,
  `createdAt`, `updatedAt`
)
SELECT
  '62ac5e28-9b24-8f6b-9ad3-078c7c4fe7fd', '2022-01-01 00:00:00.000', NULL, 'Djibouti — barème 2022 (en vigueur depuis le 1er janvier 2022)',
  400000, 0.04, 0.02, 8000,
  0.157, 0.117, 208,
  1.25, 6, 1.5,
  0.2, 0.06, 30,
  0, 0, NULL,
  CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3)
FROM DUAL
WHERE NOT EXISTS (
  SELECT 1 FROM `hr_payroll_configs` WHERE `label` = 'Djibouti — barème 2022 (en vigueur depuis le 1er janvier 2022)'
);

-- ── 2. The ITS table ───────────────────────────────────────────────────
