  ('6615d990-e0e8-8c81-b61f-1aefb1ecc72f', 'bulletin_paie', 'Bulletin de paie', 'EMPLOYEE', 'bp', '', '[{"key":"periodId","label":"Période de paie","type":"period","required":true},{"key":"issueDate","label":"Date d''émission","type":"date","default":"today"}]', 1, 1, CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3)),
  ('b9152441-6ec6-88a1-a137-5b4449d2dd00', 'bordereau_cnss', 'Bordereau CNSS — Liste du personnel', 'PERIOD', 'cnss', '', '[{"key":"issueDate","label":"Date d''émission","type":"date","default":"today"}]', 1, 1, CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3)),
  ('b1bd9e3e-c82b-88dd-a058-0722f952f458', 'ordre_virement', 'Ordre de virement', 'PERIOD', 'vir', 'Nous vous prions de bien vouloir procéder au virement des salaires du mois de {{period.labelFrLower}} au profit des bénéficiaires ci-dessous, par le débit de notre compte.', '[{"key":"issueDate","label":"Date d''émission","type":"date","default":"today"}]', 1, 1, CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
